(7513010, 1199433, 147314, '<td valign="top">Amazing, a 7 score and a ribbon and yet no single comment. I think this is a great find and a beautiful image. Congrats on the Yellow!</td>', 'Amazing, a 7 score and a ribbon and yet no single comment. I think this is a great find and a beautiful image. Congrats on the Yellow!', '2017-05-10 05:38:01.000000', NULL, 0),
(7513011, 1199459, 28742, '<td valign="top">I didn''t see the bird until now and then I thought it was someone free falling down the side of the building. I gave this a six. If I''d have noticed the bird, it might''ve been a 7. If it was a person falling, it would''ve been a 9. ;-)</td>', 'I didn''t see the bird until now and then I thought it was someone free falling down the side of the building. I gave this a six. If I''d have noticed the bird, it might''ve been a 7. If it was a person falling, it would''ve been a 9. ;-)', '2017-05-10 05:38:03.000000', NULL, 0),
