(7513028, 1199423, 118703, '<td valign="top">Wonderful light, lovely symmetry and reflections</td>', 'Wonderful light, lovely symmetry and reflections', '2017-05-10 09:31:02.000000', NULL, 0),
(7513035, 1198835, 112739, '<td valign="top">Very nice of you <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=114285" rel="nofollow" target="_blank">Neat</a>, Anita to mistake this image for one of my works. I actually have one very close to this one but decided to enter one from another perspective. As soon as I saw this one from Alessandro, I knew it would do well. Congrats on the HM Alessandro! It was a fun day!</td>', 'Very nice of you  Neat, Anita to mistake this image for one of my works. I actually have one very close to this one but decided to enter one from another perspective. As soon as I saw this one from Alessandro, I knew it would do well. Congrats on the HM Alessandro! It was a fun day!', '2017-05-10 11:17:33.000000', NULL, 0),
(7513036, 1199037, 112739, '<td valign="top">Congrats on TT Jeff!</td>', 'Congrats on TT Jeff!', '2017-05-10 11:18:59.000000', NULL, 0),
(7513037, 1199310, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting image that meets the challenge<br/> <br/>Wow, this looks an impressive place to cast off the days weary burden! The open space of this rooftop restaurant provides you with plenty of light for sure and the shapes of the square and the shadows gives you plenty of form too. Your title helps convey the party atmosphere that is certainly evident in the right corner. I assume this was your best shooting position? Its a shame the tall buildings In the background interrupt the skyline but not much you could do about that certainly from this position.</td>', 'Hello from the critique club An interesting image that meets the challenge Wow, this looks an impressive place to cast off the days weary burden! The open space of this rooftop restaurant provides you with plenty of light for sure and the shapes of the square and the shadows gives you plenty of form too. Your title helps convey the party atmosphere that is certainly evident in the right corner. I assume this was your best shooting position? Its a shame the tall buildings In the background interrupt the skyline but not much you could do about that certainly from this position.', '2017-05-10 11:20:45.000000', NULL, 0),
(7513038, 1199158, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting image that meets the challenge<br/> <br/>This certainly fulfils the challenge brief well with its capture of light and its architectural setting. I think I like that you havent taken the obvious approach of square symmetry but I think more care with the diagonal symmetry would have increased its impact. Whilst the girder with its oval shapes on the left adds some additional shape interest, overall it unbalances the image.  I like the shapes the grid reflections are making on the dome, again it adds more interest.</td>', 'Hello from the critique club An interesting image that meets the challenge This certainly fulfils the challenge brief well with its capture of light and its architectural setting. I think I like that you havent taken the obvious approach of square symmetry but I think more care with the diagonal symmetry would have increased its impact. Whilst the girder with its oval shapes on the left adds some additional shape interest, overall it unbalances the image.  I like the shapes the grid reflections are making on the dome, again it adds more interest.', '2017-05-10 11:27:50.000000', NULL, 0),
(7513041, 1199021, 112739, '<td valign="top">Congratulations Mark! Good to see you back!</td>', 'Congratulations Mark! Good to see you back!', '2017-05-10 11:57:08.000000', NULL, 0),
(7513042, 1198905, 112739, '<td valign="top">Congratulations Mike, top notch image. It''s good to see another Leica user here!</td>', 'Congratulations Mike, top notch image. It''s good to see another Leica user here!', '2017-05-10 12:00:46.000000', NULL, 0),
(7513089, 1199021, 109227, '<td valign="top">Congrats Mark; excellent image.</td>', 'Congrats Mark; excellent image.', '2017-05-10 23:40:51.000000', NULL, 0),
